mkdir -p ~/Arduino/tc_diag && cat > ~/Arduino/tc_diag/tc_diag.ino <<'EOF'
// Wiring check: select each CS in turn and read 32 bits from each DO pin.
const int CLK = 22, CS[] = {26, 28}, DO[] = {24, 30};

uint32_t read32(int cs, int dout) {
  uint32_t v = 0;
  digitalWrite(cs, LOW);
  delayMicroseconds(10);
  for (int i = 0; i < 32; i++) {
    digitalWrite(CLK, LOW); delayMicroseconds(10);
    v = (v << 1) | digitalRead(dout);
    digitalWrite(CLK, HIGH); delayMicroseconds(10);
  }
  digitalWrite(cs, HIGH);
  return v;
}

void setup() {
  Serial.begin(115200);
  pinMode(CLK, OUTPUT); digitalWrite(CLK, LOW);
  for (int c : CS) { pinMode(c, OUTPUT); digitalWrite(c, HIGH); }
  for (int d : DO) pinMode(d, INPUT_PULLUP);
  delay(500);
}

void loop() {
  for (int c : CS) for (int d : DO) {
    uint32_t v = read32(c, d);
    Serial.print("CS"); Serial.print(c); Serial.print(" DO"); Serial.print(d);
    Serial.print(" 0x"); Serial.print(v, HEX);
    if (v != 0 && v != 0xFFFFFFFF) {
      Serial.print(" tc="); Serial.print(((int32_t)v >> 18) * 0.25);
      Serial.print(" internal="); Serial.print(((int16_t)(v & 0xFFF0) >> 4) * 0.0625);
      Serial.print(" fault="); Serial.print(v & 7);
    }
    Serial.println();
  }
  Serial.println();
  delay(1000);
}
EOF
cd ~/Arduino/tc_diag && p=$(ls /dev/ttyACM* | head -1) && arduino-cli compile -b arduino:avr:megaADK -u -p $p . 2>&1 | tail -1 && stty -F $p 115200 raw -echo && timeout 4 cat $p | head -12

mkdir -p ~/Arduino/tc_fault && cat > ~/Arduino/tc_fault/tc_fault.ino <<'EOF'
// Print MAX31855 fault bits and cold-junction temp for both boards.
#include <Adafruit_MAX31855.h>
Adafruit_MAX31855 tc[] = {Adafruit_MAX31855(22, 26, 24), Adafruit_MAX31855(28, 32, 30)};

void setup() {
  Serial.begin(115200);
  for (auto &t : tc) t.begin();
  delay(500);
}

void loop() {
  for (int i = 0; i < 2; i++) {
    float c = tc[i].readCelsius();
    uint8_t e = tc[i].readError();
    Serial.print("TC"); Serial.print(i + 1);
    Serial.print(" tc="); Serial.print(c);
    Serial.print(" board="); Serial.print(tc[i].readInternal());
    Serial.print(" fault=");
    if (!e) Serial.print("none");
    if (e & MAX31855_FAULT_OPEN) Serial.print("OPEN ");
    if (e & MAX31855_FAULT_SHORT_GND) Serial.print("SHORT_GND ");
    if (e & MAX31855_FAULT_SHORT_VCC) Serial.print("SHORT_VCC ");
    Serial.println();
  }
  delay(1000);
}
EOF
